    if (max != null) ps.add(cb.le(p.get("price"), max));
    cq.where(ps.toArray(new Predicate[0])).orderBy(cb.asc(p.get(Set.of("name", "price").contains(sort) ? sort : "name")));
    return em.createQuery(cq).setMaxResults(50).getResultList();
}

